+
+internal sealed class OriginalRectangleHalfLinesDocument : IScribeDocumentDefinition
+{
+    private static Formula Call(string name, params Formula[] args)
+    {
+        Formula f = F.Seq(Operatorname, Grp(F.Id(name)), Open);
+        for (int i = 0; i < args.Length; i++)
+            f = i == 0 ? F.Seq(f, args[i]) : F.Seq(f, Comma, Sp, args[i]);
+        return F.Seq(f, Close);
+    }
+    private static Formula Par(Formula f) => F.Seq(Open, f, Close);
+    private static Formula All(string name, Formula type, Formula body) =>
+        F.Seq(Forall, Sp, F.Id(name), Colon, Par(type), Comma, Sp, Par(body));
+    private static Formula Lam(string name, Formula type, Formula body) =>
+        F.Seq(Open, F.Id(name), Colon, type, Mapsto, Sp, body, Close);
+    private static Formula Rel(Formula a, Formula relation, Formula b) => F.Seq(a, relation, Sp, b);
+    private static Formula Imp(Formula a, Formula b) => F.Seq(Par(a), Implies, Sp, Par(b));
+    private static Formula MinusOf(Formula a, Formula b) => F.Seq(Par(a), Minus, Par(b));
+    private static Formula Ands(params Formula[] terms)
+    {
+        Formula f = terms[0];
+        for (int i = 1; i < terms.Length; i++) f = F.Seq(f, Land, Sp, Par(terms[i]));
+        return f;
+    }
+    private static Formula Visible() => F.Seq(F.Id("Int"), To, Sp, F.Id("Bool"));
+    private static Formula AE(Formula p, Formula body) => Call("AE", p, Lam("z", Visible(), body));
+    private static Formula RecordFormula()
+    {
+        var k=F.Id("k"); var n=F.Id("n"); var z=F.Id("z");
+        return All("k", F.Id("Nat"), All("n", F.Id("Nat"),
+            Rel(Call("recordField", k, n), Eq, Call("generatedField",
+                Lam("z", Visible(), Call("pair", Call("leftWord", k, z), Call("rightWord", n, z)))))));
+    }
+    private static Formula BoundsFormula()
+    {
+        var p=F.Id("P"); var y=F.Id("Y"); var j=F.Id("j");
+        var k=F.Id("k"); var n=F.Id("n"); var z=F.Id("z");
+        var bl=F.Id("BL"); var br=F.Id("BR"); var nat=F.Id("Nat");
+        var vr=F.Seq(Par(Visible()), To, Sp, F.Id("Real"));
+        Formula CE(Formula field) => Call("condExp", p, y, field, z);
+        Formula Diff(Formula a, Formula b, Formula bound) =>
+            Rel(Call("abs", MinusOf(CE(a), CE(b))), Le, Call("apply", bound, z));
+        var field=Call("recordField", k, n);
+        var hl=All("k", nat, All("n", nat, Imp(Rel(j, Le, k),
+            AE(p, Diff(field, Call("recordField", j, n), bl)))));
+        var hr=All("k", nat, All("n", nat, Imp(Rel(j, Le, n),
+            AE(p, Diff(field, Call("recordField", k, j), br)))));
+        var result=Ands(
+            AE(p, Diff(Call("generatedField", F.Id("exterior")),
+                Call("generatedField", Call("leftObservation", j)), bl)),
+            AE(p, Diff(Call("generatedField", F.Id("exterior")),
+                Call("generatedField", Call("rightObservation", j)), br)));
+        return All("P", Call("Measure", Visible()), F.Seq(
+            OpenBracket, Call("IsProbabilityMeasure", p), CloseBracket,
+            All("Y", vr, All("j", nat, All("BL", vr, All("BR", vr,
+                Imp(hl, Imp(hr, result))))))));
+    }
+
+    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
+        "Finite record bounds and the entire opposite half-line", H("Finite record bounds and the entire opposite half-line"),
+        Blocks(
+            Describe.Lean(DescribeId.Create("record-field"),
+                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/Rectangles/OriginalRectangleHalfLines.recordField"),
+                H("The exact finite erased observation field"), StatementSource.FromAuthor(Disp(RecordFormula())), AssessedProvenance.FromRepo(),
+                Blocks(Paragraph(Text("For natural k and n, recordField(k,n) is the sigma-field on the original visible integer-time path generated by the chronological words X[-k,-1] and X[1,n]. The erased coordinate X0 is absent, and either observed word may be empty."))), DescribeRole.Definition),
+            Describe.Lean(DescribeId.Create("finite-record-bounds-to-half-lines"),
+                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/Rectangles/OriginalRectangleHalfLines.finite_record_bounds_to_half_lines"),
+                H("Two ordered limits preserve the same finite bound"), StatementSource.FromAuthor(Disp(BoundsFormula())), AssessedProvenance.FromRepo(),
+                Blocks(Paragraph(Text("Fix any one probability measure P on the original visible integer-time path space, real-valued function Y, natural retained length j and real-valued bounds B_L and B_R. Suppose for every k,n with k>=j the absolute difference between the P conditional expectations of Y given recordField(k,n) and recordField(j,n) is at most B_L almost everywhere. Suppose also that for every k,n with n>=j the corresponding difference for recordField(k,n) and recordField(k,j) is at most B_R. Then the full exterior conditional expectation differs from the conditional expectation given (leftWord(j),after) by at most B_L almost everywhere, and from that given (before,rightWord(j)) by at most B_R almost everywhere. Here before and after are the entire infinite visible half-lines, and exterior is their pair. Both conclusions use the original P and exactly the original bound functions. The left argument first completes k and then n. The right argument first completes n and then k. Each passage uses almost-sure upward conditional-expectation convergence and closedness of the scalar inequality, on a common countable intersection of full-measure events. No L2 convergence claim is needed."))), DescribeRole.Theorem),
+            Paragraph(Text("In the formulas, generatedField(f) means MeasurableSpace.comap(f) with the canonical product measurable space on the observation type. condExp(P,Y,m,z) is the value at z of the P conditional expectation of Y given m, and AE(P,(z maps to p)) means p holds P-almost everywhere. Int, Nat, Bool and Real denote the corresponding Lean types.")),
+            Paragraph(Text("The finite fields split into the join of the left-word and right-word fields. The supremum of the chronological left-word fields is exactly the before field, and the supremum of the right-word fields is exactly the after field: each finite word is a measurable function of its half-line, while every half-line coordinate occurs in some finite word. Taking these joins proves all four supremum identities used by the two ordered limits. Thus no retained infinite half-line is replaced by a finite window at the last step, including j=0.")),
+            Paragraph(Text("In rectangle smoothing, take Y=erasedBit and P to be the visible pushforward of the one native class-restricted original joint law. The intended bounds are rho raised to the left and right original visible success counts. The finite_record_smoothing_by_original_success_count supplier provides bounds for its finite recordPosterior ratios on positive records. Identifying those ratios with these conditional expectations, discarding zero record fibers only on their null sets, and matching the two count conventions are the finite adapters needed before the present limit theorem applies. The chronological_success_moment estimate then controls the squared count under the same original law. Squaring and integrating the resulting posterior bounds and summing the quotient groups gives the separate squared-defect and root-tail conclusions.")))));
+}

